import SwiftUI
import UniformTypeIdentifiers

struct TripsPage:View{
    @EnvironmentObject var store:Store
    var body:some View{ScrollView{VStack(alignment:.leading,spacing:22){HStack(alignment:.top){Heading(title:tF("把沿途，装订成册。","Bind the journey into a book."),subtitle:tF("一次旅行，一组城市，一段值得重读的记忆。","One trip, a set of cities, a memory worth rereading."));Spacer();Button{store.tripEditor=Trip(name:"")}label:{Label(tF("新建旅行","New Trip"),systemImage:"plus")}.buttonStyle(.borderedProminent)}
        if store.journal.trips.isEmpty{Panel{EmptyJournal(symbol:"book.closed",title:tF("旅行的第一页，等你写下","The first page of your travels awaits"),subtitle:tF("可以先创建旅行，再把去过的城市放进来。","Create a trip first, then add the cities you visited."))}}
        LazyVGrid(columns:[GridItem(.adaptive(minimum:300),spacing:18)],spacing:18){ForEach(store.journal.trips.sorted{$0.createdAt>$1.createdAt}){trip in tripCard(trip)}}
    }.padding(28).frame(maxWidth:1250).frame(maxWidth:.infinity,alignment:.leading)}}
    func tripCard(_ trip:Trip)->some View{
        let visits=store.journal.visits.filter{$0.tripID==trip.id}.sorted{$0.date.sortKey<$1.date.sortKey}
        let cities=Set(visits.map(\.cityID)).compactMap{store.cityIndex[$0]}.sorted{$0.name<$1.name}
        let photo=visits.flatMap(\.photoIDs).first
        return Panel{VStack(alignment:.leading,spacing:15){HStack(alignment:.top){if let photo{PhotoTile(url:store.photoURL(photo),size:70)}else{Tile(symbol:"suitcase.rolling").frame(width:70,height:70)};VStack(alignment:.leading,spacing:7){Text(trip.name).font(.system(size:17,weight:.semibold));Text(tF("\(cities.count) 座城市 · \(visits.count) 次到访","\(cities.count) cities · \(visits.count) visits")).font(.caption).foregroundStyle(.secondary)};Spacer();Menu{Button(tF("编辑旅行","Edit Trip")){store.tripEditor=trip};Button(tF("删除旅行，保留足迹","Delete trip, keep footprints")){store.alertDelete({store.deleteTrip(trip)},title:tF("删除这次旅行？","Delete this trip?"),detail:tF("只移除旅行分组，全部足迹与照片仍保留。","Only the trip grouping is removed; all footprints and photos are kept."))}}label:{Image(systemName:"ellipsis")}.menuStyle(.borderlessButton).frame(width:22)}
            if let first=visits.first,let last=visits.last{Text(first.date.label == last.date.label ? first.date.label : "\(first.date.label) — \(last.date.label)").font(.caption).foregroundStyle(.secondary)}
            Text(cities.isEmpty ? tF("还没有收录城市","No cities yet") : cities.map(\.name).joined(separator:" · ")).font(.system(size:13)).lineLimit(3).frame(maxWidth:.infinity,alignment:.leading)
            if !trip.note.isEmpty{Text(trip.note).font(.caption).foregroundStyle(.secondary).lineLimit(3)}
            Divider();HStack{Button(tF("添加足迹","Add Footprint")){store.editor=EditorRequest(tripID:trip.id)};Spacer();Button(tF("在地图查看","View on Map")){store.tripFilter=trip.id;store.year=0;store.section="地图"}}.font(.caption).buttonStyle(.plain).foregroundStyle(Theme.teal)
        }}
    }
}
struct TimelinePage:View{
    @EnvironmentObject var store:Store
    var groups:[Int]{Array(Set(store.filteredVisits.map{$0.date.year ?? 0})).sorted(by:>)}
    var body:some View{ScrollView{VStack(alignment:.leading,spacing:24){HStack(alignment:.top){Heading(title:tF("翻过一页，又是一程。","Turn the page, another journey."),subtitle:tF("按年份回看每一段足迹。","Look back on every footprint by year."));Spacer();Picker(tF("年份","Year"),selection:$store.year){Text(tF("所有年份","All Years")).tag(0);ForEach(store.years,id:\.self){Text(tF("\($0) 年","\($0)")).tag($0)}}.frame(width:140);if !store.tripFilter.isEmpty{Button(tF("全部旅行","All Trips")){store.tripFilter=""}}}
        Panel{HStack{StatItem(value:String(store.metrics.cities),label:tF("到访城市","Cities Visited"));StatItem(value:String(store.metrics.newCities),label:store.year == 0 ? tF("首次年份已知的城市","Cities with known first year") : tF("首次到访城市","First-time Cities"));StatItem(value:String(store.metrics.revisits),label:tF("再次到访","Revisits"));StatItem(value:String(store.metrics.trips),label:tF("关联旅行","Linked Trips"))}}
        Text(tF("新增按实际到访年份计算。存在时间未知的更早记录时，不判定首次年份；重访次数按记录顺序去重。","New counts use the actual visit year. When earlier records have unknown dates, the first year is not determined; revisits are deduplicated in record order.")).font(.caption).foregroundStyle(.secondary)
        if store.filteredVisits.isEmpty{Panel{EmptyJournal(symbol:"clock",title:tF("还没有写下的岁月","No years written yet"),subtitle:tF("在地图上添加足迹，时间轴会慢慢长出来。","Add footprints on the map and the timeline will grow."))}}
        ForEach(groups,id:\.self){year in VStack(alignment:.leading,spacing:14){HStack{Text(year==0 ? tF("时间未详","Date Unknown") : String(year)).font(.system(size:22,weight:.semibold));Rectangle().fill(Color.primary.opacity(0.12)).frame(height:1)}
            let records=store.filteredVisits.filter{($0.date.year ?? 0)==year}.sorted{$0.date.sortKey == $1.date.sortKey ? $0.createdAt>$1.createdAt : $0.date.sortKey>$1.date.sortKey}
            let tripIDs=Array(Set(records.compactMap(\.tripID))).sorted()
            ForEach(tripIDs,id:\.self){tid in if let trip=store.journal.trips.first(where:{$0.id==tid}){Panel{VStack(alignment:.leading,spacing:14){HStack{Image(systemName:"book.closed").foregroundStyle(Theme.teal);Text(trip.name).font(.headline);Spacer();Text(year == 0 ? tF("日期未详","Date unknown") : tF("本年片段","This year's moments")).font(.caption2).foregroundStyle(.secondary)};ForEach(records.filter{$0.tripID==tid}){v in row(v)}}}}}
            ForEach(records.filter{$0.tripID==nil}){v in Panel{row(v)}}
        }}
    }.padding(28).frame(maxWidth:1250).frame(maxWidth:.infinity,alignment:.leading)}}
    func row(_ visit:Visit)->some View{HStack(alignment:.top,spacing:15){Image(systemName:"mappin.circle.fill").foregroundStyle(Theme.teal).font(.system(size:22));VStack(alignment:.leading,spacing:6){HStack{Button(store.cityIndex[visit.cityID]?.name ?? tF("未知地点","Unknown place")){store.selectedCity=visit.cityID;store.section="地图"}.buttonStyle(.plain).font(.system(size:16,weight:.medium));Text(visit.date.label).font(.caption).foregroundStyle(.secondary)};if !visit.note.isEmpty{Text(visit.note).font(.system(size:12)).foregroundStyle(.secondary).lineLimit(3)}};Spacer();if let id=visit.photoIDs.first{PhotoTile(url:store.photoURL(id),size:48)};Menu{Button(tF("编辑足迹","Edit Footprint")){store.editor=EditorRequest(visit:visit)};Button(tF("删除足迹","Delete Footprint")){store.alertDelete({store.remove(visit)},title:tF("删除足迹？","Delete this footprint?"),detail:tF("本次到访将被移除，之后可撤销。","This visit will be removed; you can undo afterwards."))}}label:{Image(systemName:"ellipsis")}.menuStyle(.borderlessButton).frame(width:20)}}
}
struct SettingsPage:View{
    @EnvironmentObject var store:Store
    @State var showSources=false
    @State var showCatalog=false
    @State var listQuery=""
    @State private var showResidentCityEditor = false
    var version:String{Bundle.main.object(forInfoDictionaryKey:"CFBundleShortVersionString") as? String ?? "1.7"}
    var body:some View{ScrollView{VStack(alignment:.leading,spacing:22){Heading(title:tF("设置","Settings"),subtitle:tF("妥善收藏，每一段足迹。","Keep every footprint well."))
        Panel{VStack(alignment:.leading,spacing:16){Label(tF("个人与外观","Personal & Appearance"),systemImage:"person.crop.square").font(.headline);HStack{Text(tF("地图铭牌","Map Nameplate"));TextField(tF("你的名字（可不填）","Your name (optional)"),text:$store.ownerName).textFieldStyle(.roundedBorder).frame(width:240);Spacer()};Toggle(tF("保存时播放轻音效","Play a soft sound on save"),isOn:$store.soundEnabled);Toggle(tF("界面过渡动画","Interface transition animations"),isOn:$store.animationEnabled);Text(tF("动画同时遵循系统“减少动态效果”。地图使用固定羊皮纸配色，保证收藏地图与导出一致。","Animations also respect the system's Reduce Motion setting. The map uses a fixed parchment palette so the collection map matches its exports.")).font(.caption).foregroundStyle(.secondary)}}
        Panel { ResidentCitySummary { showResidentCityEditor = true } }
        Panel{VStack(alignment:.leading,spacing:15){Label(tF("资料与备份","Data & Backup"),systemImage:"externaldrive").font(.headline);Text(tF("\(store.journal.visits.count) 条足迹 · \(store.journal.trips.count) 次旅行 · \(store.journal.attachments.count) 张照片副本","\(store.journal.visits.count) footprints · \(store.journal.trips.count) trips · \(store.journal.attachments.count) photo copies")).font(.caption).foregroundStyle(.secondary);HStack{Button(tF("导出完整备份","Export Full Backup")){store.exportBackup()}.buttonStyle(.borderedProminent);Button(tF("恢复完整备份","Restore Full Backup")){store.restoreBackup()};Button(tF("打开资料库","Open Library")){if let url=store.repo?.root{NSWorkspace.shared.open(url)}}};Divider();HStack{Button(tF("导出 CSV","Export CSV")){store.saveFile(name:"足迹记录.csv",type:.commaSeparatedText){Data(Repository.csv(store.journal,cities:store.cityIndex).utf8)}};Button(tF("导出 JSON","Export JSON")){store.saveFile(name:"足迹记录.json",type:.json){try encoder.encode(store.journal)}}};Text(tF("完整备份包含照片，可迁移到另一台 Mac；CSV / JSON 不包含照片。单次完整备份支持照片合计 350 MB、备份文件 500 MB 内。恢复为整体替换，替换前会保留原数据备份。","A full backup includes photos and can be migrated to another Mac; CSV / JSON do not include photos. One full backup supports up to 350 MB of photos and a 500 MB backup file. Restoring replaces everything; the current data is kept as a pre-restore backup.")).font(.caption).foregroundStyle(.secondary).lineSpacing(4);Text(tF("每天首次保存保留一份本地快照，最近 7 个日期；快照依赖本机照片，不是异地备份。为了支持撤销和历史快照，删除记录不会立即清理照片副本。","The first save of each day keeps a local snapshot for the last 7 dates; snapshots rely on local photos and are not off-site backups. To support undo and history snapshots, deleting records does not immediately remove photo copies.")).font(.caption).foregroundStyle(.secondary).lineSpacing(4)}}
        Panel{VStack(alignment:.leading,spacing:15){Label(tF("地图与统计口径","Map & Statistics"),systemImage:"map").font(.headline);Text(tF("离线地点 \(store.geography.cities.count) 个 · 中国收集单元 \(store.chinaTotal) 个\n世界国家 / 地区展示去重到访数，不以地图多边形数计算完成率。","\(store.geography.cities.count) offline places · \(store.chinaTotal) China collection units\nWorld countries / regions show deduplicated visit counts; completion is not based on map polygon counts.")).font(.system(size:13)).lineSpacing(5);Text(tF("中国普通地级市、自治州、地区、盟及省直辖县级单位分别收集；四个直辖市、香港、澳门、台湾各计一个特殊单元。370 是内置清单数量，不是最新法定地级行政区数量。台湾细分尚待数据核对。南极为特别足迹，不计国家、城市或六洲完成率。","China's prefecture-level cities, autonomous prefectures, regions, leagues and province-administered county-level units are collected separately; the four municipalities, Hong Kong, Macau and Taiwan each count as one special unit. 370 is the built-in list size, not the latest statutory count of prefecture-level divisions. Taiwan's subdivisions await data verification. Antarctica is a special footprint and does not count toward country, city or six-continent completion.")).font(.caption).foregroundStyle(.secondary).lineSpacing(4);HStack{Button(tF("查看中国收集清单","View China Collection List")){showCatalog=true};Button(tF("地图来源与许可","Map Sources & Licenses")){showSources=true}};Text(tF("地图用于私人旅行收藏，基于公开数据制作示意图，非导航或行政区划权威依据。地图源数据版本与署名随安装包保留。","The map is for private travel collection, a schematic made from public data, not an authoritative reference for navigation or administrative divisions. Source data versions and attributions are kept with the installer.")).font(.caption).foregroundStyle(.secondary)}}
        HStack{Image(systemName:"lock.shield");Text(tF("搞足迹 V\(version) · 完全离线 · 无账号 · 不请求定位","Gao Footprints V\(version) · Fully offline · No account · Never requests location"));Spacer()}.font(.caption).foregroundStyle(.secondary)
    }.padding(28).frame(maxWidth:900,alignment:.leading)}
    .sheet(isPresented:$showResidentCityEditor){ResidentCityEditor().environmentObject(store)}
    .sheet(isPresented:$showSources){VStack(alignment:.leading,spacing:16){Text(tF("数据来源与许可","Data Sources & Licenses")).font(.title2);ScrollView{Text(sourceText).font(.system(size:12,design:.monospaced)).textSelection(.enabled).frame(maxWidth:.infinity,alignment:.leading)};Button(tF("关闭","Close")){showSources=false}}.padding(24).frame(width:720,height:550)}
    .sheet(isPresented:$showCatalog){VStack(alignment:.leading,spacing:15){Text(tF("中国城市收集 · \(store.chinaTotal) 个单元","China City Collection · \(store.chinaTotal) units")).font(.title2);TextField(tF("筛选名称或省份","Filter by name or province"),text:$listQuery).textFieldStyle(.roundedBorder);List(store.results(listQuery,country:"CHN",limit:1000)){c in HStack{Text(c.name);Spacer();Text(c.province).foregroundStyle(.secondary);if store.allVisitedIDs.contains(c.id){Image(systemName:"checkmark.seal.fill").foregroundStyle(Theme.teal)}}};Button(tF("关闭","Close")){showCatalog=false}}.padding(24).frame(width:600,height:550)}
    }
    var sourceText:String{(FootprintsBundle.bundle.url(forResource:"THIRD_PARTY_NOTICES",withExtension:"txt").flatMap{try?String(contentsOf:$0,encoding:.utf8)}) ?? tF("来源说明不可用，请重新安装完整应用。","Source notices unavailable; please reinstall the full app.")}
}
